INSERT INTO statutory_rules(code,effective_from,effective_to_exclusive,unit,value_num,instrument_ko,article_ko,promulgation_ko,enforced_on,source_url,retrieved_on,provenance_ko,filing_rule)
SELECT t.code,(h.data->>'from_on')::date,(h.data->>'to_on')::date,
 CASE WHEN config->'deadline'->>'kind'='DAY_OF_NEXT_MONTH' THEN 'DAY_OF_NEXT_MONTH' ELSE 'DAYS' END,
 COALESCE((config->'deadline'->>'value')::int,0),h.data->>'law',config->>'article',h.data->>'promulgation',(h.data->>'from_on')::date,h.data->>'url',DATE '2026-10-12',
 '노무사 검토 전 · 연혁 조문 원문 확인 완료. 이전 법령의 적용 대상 사실과 과태료는 별도 검토. 검토 영수증으로 RELEASED 전까지 HOLD.',
 t.filing_rule || jsonb_build_object('effective_from',h.data->>'from_on','effective_to_exclusive',h.data->>'to_on','deadline',config->'deadline','candidate',config->'candidate',
 'open',true,'penalty',NULL,'exclusions','[]'::jsonb,'applicability_unverified',true,'applicability_citations','[]'::jsonb,
 'citation',jsonb_build_object('instrument',h.data->>'law','article',config->>'article','promulgation',h.data->>'promulgation','enforced_on',h.data->>'from_on','source_url',h.data->>'url'))
FROM history h JOIN templates t ON t.filing_rule->>'insurer'=h.data->>'insurer'
CROSS JOIN LATERAL (SELECT h.data->'configs'->(t.filing_rule->>'filing_kind') AS config) c WHERE config IS NOT NULL;
